	t.Parallel()

	m := newModel(context.Background(), nil)
	if m.tabs.SelectedID() != "bookmarks" {
		t.Fatalf("unexpected default bottom view: %s", m.tabs.SelectedID())
	}

	next, _ := m.Update(tea.KeyPressMsg{Text: "/"})
